-- ============================================================
-- 13_tipo_contacto_array.sql
-- Convierte contacts.tipo_contacto de varchar a text[] (lista)
-- y sincroniza los tipos según data limpia de Odoo (contactos.xlsx)
-- 598 contactos: 154 solo cliente, 383 solo proveedor, 61 ambos
-- Ejecutar en Supabase SQL Editor. Idempotente.
-- ============================================================

-- 1. Quitar CHECK anterior y convertir la columna a lista
ALTER TABLE public.contacts DROP CONSTRAINT IF EXISTS contacts_tipo_contacto_check;

DO $$
BEGIN
  IF (SELECT data_type FROM information_schema.columns
      WHERE table_schema='public' AND table_name='contacts'
        AND column_name='tipo_contacto') <> 'ARRAY' THEN
    ALTER TABLE public.contacts
      ALTER COLUMN tipo_contacto TYPE text[]
      USING CASE lower(tipo_contacto)
        WHEN 'ambos' THEN ARRAY['cliente','proveedor']
        ELSE ARRAY[lower(tipo_contacto)]
      END;
  END IF;
END $$;

-- 2. Nuevo CHECK: solo valores permitidos y lista no vacía
ALTER TABLE public.contacts
  ADD CONSTRAINT contacts_tipo_contacto_check
  CHECK (tipo_contacto <@ ARRAY['cliente','proveedor','empleado','otro']
         AND array_length(tipo_contacto, 1) >= 1);

-- Índice GIN para búsquedas por tipo (WHERE tipo_contacto @> ARRAY['cliente'])
CREATE INDEX IF NOT EXISTS idx_contacts_tipo_contacto
  ON public.contacts USING gin (tipo_contacto);

-- 3. Sincronizar tipos desde data limpia de Odoo.
--    Si el nro_documento ya existe: solo actualiza tipo_contacto.
--    Si no existe: inserta el contacto con datos básicos.
ON CONFLICT (nro_documento) DO UPDATE
  SET tipo_contacto = EXCLUDED.tipo_contacto,
      updated_at    = now();

-- 4. Verificación
SELECT unnest(tipo_contacto) AS tipo, count(*)
FROM public.contacts GROUP BY 1 ORDER BY 1;
